                    if "parsed_resume_json" in params:
                        candidate_state["parsed_resume_json"] = json.loads(
                            params["parsed_resume_json"]
                        )
                    return FakeResult()
                if (
                    "INSERT INTO candidate_preferences" in sql
                    or "UPDATE candidate_preferences" in sql
                ):
