        List fields are merged and ``profile_deletions`` removes specific items from
        profile sections.
        """
        safe = {
            k: v for k, v in updates.items() if k in VALID_UPDATE_FIELDS and v is not None
        }
        if not safe:
            return {"updated": False, "deleted": {}}

