        existing = await _get_candidate_row_for_update(db, candidate_id)
        existing_raw = _parse_raw_data(existing.get("raw_data"))

        set_clauses = []
        params: dict = {"cid": candidate_id}
        current_role_set = False
        raw_data_changed = False
