                self._rows = rows or []

            def mappings(self):
                return self

            def fetchone(self):
                return self._rows[0] if self._rows else None

            def scalar(self):
                return None

        class FakeSession:
            async def __aenter__(self):
                return self

            async def __aexit__(self, *a):
                return False

            async def execute(self_inner, statement, params=None):
                sql = str(statement)
                params = params or {}
                # Reject any attempt to set profile_deletions as a column
                assert "profile_deletions" not in sql or "profile_deletions" not in (
                    params or {}
                ), f"profile_deletions must not appear in SQL params: {sql}"
                # Supplemental profile fields are persisted inside raw_data, not as
                # physical candidates columns.
