                )
                if merged != (existing.get("work_experience") or []):
                    set_clauses.append("work_experience = CAST(:work_experience AS json)")
                    params["work_experience"] = json.dumps(merged)
            elif field == "education":
                if not isinstance(value, list):
                    continue
                value = [
                    item
                    for item in value
