                    if "raw_data" in params:
                        candidate_state["raw_data"] = json.loads(params["raw_data"])
                    return FakeResult()
                if (
                    "INSERT INTO candidate_preferences" in sql
                    or "UPDATE candidate_preferences" in sql
                ):
