                sql = str(statement)
                params = params or {}
                executed.append((sql, params))
                if "SELECT * FROM candidates WHERE id = :cid LIMIT 1" in sql:
                    return FakeResult([candidate_state])
                if "FROM candidate_preferences" in sql and "SELECT" in sql:
                    return FakeResult([])
                if "UPDATE candidates SET" in sql:
