            elif field == "bio":
                new_bio = str(value).strip()
                if not new_bio:
                    continue
                if new_bio != (existing.get("summary") or ""):
                    set_clauses.append("summary = :bio")
                    params["bio"] = new_bio
            elif field == "experience_years":
                try:
