            "candidate": {
                "id": "candidate-4",
                "raw_data": {},
                "skills": [],
                "work_experience": [],
                "education": [],
                "location": "",
                "summary": "",
                "current_role": "",
                "experience_years": None,
            }
        }

        class FakeResult:
            def __init__(self, rows=None, scalar_value=None):
                self._rows = rows or []
                self._scalar_value = scalar_value

            def mappings(self):
                return self

            def fetchone(self):
                return self._rows[0] if self._rows else None

            def scalar(self):
                return self._scalar_value

        class FakeSession:
            async def __aenter__(self):
                return self

            async def __aexit__(self, exc_type, exc, tb):
                return False

            async def execute(self, statement, params=None):
                sql = str(statement)
                params = params or {}
                if "SELECT * FROM candidates WHERE id = :cid LIMIT 1" in sql:
                    return FakeResult([state["candidate"]])
                if "UPDATE candidates SET" in sql and "current_role" in params:
                    state["candidate"]["current_role"] = params["current_role"]
                    return FakeResult()
                return FakeResult()

            async def commit(self):
                return None

        monkeypatch.setattr(server, "SessionLocal", lambda: FakeSession())

